manifest = await yuki_workspace_read({"path": "/workspace/manifest.txt"})
files = [l for l in manifest["data"]["text"].splitlines() if l.strip()]
recs = {}
for f in files:
    r = await yuki_workspace_read({"path": "/workspace/" + f})
    for line in r["data"]["text"].splitlines()[1:]:
        if not line.strip(): continue
        rid, region, amount, status = line.split(",")
        recs.setdefault(rid, (region, amount, status))
cnt = {"A":0,"B":0,"C":0,"D":0}
tot = {"A":0,"B":0,"C":0,"D":0}
voidc = {"A":0,"B":0,"C":0,"D":0}
for rid, (region, amount, status) in recs.items():
    if status == "void":
        voidc[region] += 1
    else:
        cnt[region] += 1
        tot[region] += int(amount)
out = ""
for reg in ["A","B","C","D"]:
    out += "%s\t%d\t%d\n" % (reg, cnt[reg], tot[reg])
    print(reg, "ok", cnt[reg], "sum", tot[reg], "void", voidc[reg])
