lst = await yuki_workspace_list({"path": "/workspace/nodes"})
names = [it["path"] for it in lst["data"]["items"]]
reads = await asyncio.gather(*[yuki_workspace_read({"path": n}) for n in names])
nodes = {}
for n, r in zip(names, reads):
    txt = r["data"]["text"]
    d = {}
    for line in txt.strip().split("\n"):
        if "=" in line:
            k, v = line.split("=", 1)
            d[k.strip()] = v.strip()
    nodes[n] = d

chain = []
cur = "nodes/34aaa432.txt"
seen = set()
while True:
    if cur in seen:
        chain.append(("LOOP", cur)); break
    seen.add(cur)
    node = nodes.get(cur)
    if node is None:
        chain.append(("MISSING", cur)); break
    val = int(node["value"])
    chain.append((cur, val))
    if node.get("left") == "END" or node.get("right") == "END":
        break
    nxt = node["left"] if val % 2 == 0 else node["right"]
    if nxt == "END" or nxt not in nodes:
        if nxt == "END":
            pass
        cur = nxt
        if cur == "END":
            break
    cur = nxt

